/* ---------- multi-file ZIP app server (LX.zapps runtime) ----------
   Installed zip apps store every file in IndexedDB (db "lx-zapps", store
   "files", key "appId/relPath"). This handler serves them at
   /…/~zapps/<appId>/<relPath> so relative css/js/img links inside the app
   resolve naturally — fully offline. */
const ZDB = 'lx-zapps';
const ZMIMES = {
  html: 'text/html; charset=utf-8', htm: 'text/html; charset=utf-8', css: 'text/css; charset=utf-8',
  js: 'text/javascript; charset=utf-8', mjs: 'text/javascript; charset=utf-8',
  json: 'application/json; charset=utf-8', webmanifest: 'application/manifest+json; charset=utf-8',
  map: 'application/json; charset=utf-8', txt: 'text/plain; charset=utf-8', md: 'text/plain; charset=utf-8',
  csv: 'text/plain; charset=utf-8', xml: 'application/xml; charset=utf-8', svg: 'image/svg+xml',
  png: 'image/png', jpg: 'image/jpeg', jpeg: 'image/jpeg', gif: 'image/gif', webp: 'image/webp',
  avif: 'image/avif', bmp: 'image/bmp', ico: 'image/x-icon', woff: 'font/woff', woff2: 'font/woff2',
  ttf: 'font/ttf', otf: 'font/otf', mp3: 'audio/mpeg', wav: 'audio/wav', ogg: 'audio/ogg',
  m4a: 'audio/mp4', aac: 'audio/aac', flac: 'audio/flac', mp4: 'video/mp4', webm: 'video/webm',
  mov: 'video/quicktime', wasm: 'application/wasm', pdf: 'application/pdf',
};
function zMime(p) {
  const m = /[.]([a-z0-9]+)$/.exec(String(p).toLowerCase());
  return (m && ZMIMES[m[1]]) || 'application/octet-stream';
}
function zdb() {
  return new Promise((resolve, reject) => {
    const rq = indexedDB.open(ZDB, 1);
    rq.onupgradeneeded = () => {
      const d = rq.result;
      if (!d.objectStoreNames.contains('files')) d.createObjectStore('files', { keyPath: 'key' });
      if (!d.objectStoreNames.contains('meta')) d.createObjectStore('meta', { keyPath: 'appId' });
    };
    rq.onsuccess = () => resolve(rq.result);
    rq.onerror = () => reject(rq.error);
  });
}
function zget(store, key) {
  return new Promise((resolve) => {
    const rq = store.get(key);
    rq.onsuccess = () => resolve(rq.result || null);
    rq.onerror = () => resolve(null);
  });
}
async function serveZapp(appId, path) {
  path = decodeURIComponent(path || '');
  if (!path || path.charAt(path.length - 1) === '/') path += 'index.html';
  if (path.split('/').indexOf('..') >= 0) return new Response('Bad path', { status: 400 });
  try {
    const d = await zdb();
    const rec = await zget(d.transaction('files', 'readonly').objectStore('files'), appId + '/' + path);
    if (!rec) return new Response(
      '<!DOCTYPE html><html><head><meta charset="utf-8"><title>404</title></head>' +
      '<body style="margin:0;height:100vh;display:grid;place-items:center;background:#141822;color:#e9edf5;' +
      'font-family:-apple-system,Segoe UI,system-ui,sans-serif">' +
      '<div style="text-align:center"><div style="font-size:44px">&#128230;</div>' +
      '<h2 style="margin:8px 0 4px">File not found</h2>' +
      '<p style="color:#a9b3c7;font-size:13px;margin:0">' + path + ' is not part of this app.<br>' +
      'Reinstall it from the App Store if this keeps happening.</p></div></body></html>',
      { status: 404, headers: { 'Content-Type': 'text/html; charset=utf-8' } });
    return new Response(rec.data, {
      headers: { 'Content-Type': rec.mime || zMime(path), 'Cache-Control': 'no-store', 'X-LX-Zapp': appId },
    });
  } catch (err) {
    return new Response('App storage error: ' + (err && err.message), { status: 500, headers: { 'Content-Type': 'text/plain' } });
  }
}

self.addEventListener('install', (e) => {
  e.waitUntil((async () => {
    const cache = await caches.open(CACHE);
    let ok = 0, fail = 0;
    await Promise.all(PRECACHE.map(async (entry) => {
      const url = entry.split('#')[0];
      try { await cache.add(new Request(url, { cache: 'reload' })); ok++; }
      catch (err) { fail++; console.warn('[sw] miss', url, err && err.message); }
    }));
    if (fail === 0) {
      await self.clients.matchAll().then((cls) => cls.forEach((cl) => cl.postMessage({ type: 'OFFLINE_READY' })));
      self.skipWaiting();
    }
  })());
});

self.addEventListener('activate', (e) => {
  e.waitUntil((async () => {
    const keys = await caches.keys();
    await Promise.all(keys.filter((k) => k !== CACHE).map((k) => caches.delete(k)));
    await self.clients.claim();
    await self.clients.matchAll().then((cls) => cls.forEach((cl) => cl.postMessage({ type: 'OFFLINE_READY' })));
  })());
});

self.addEventListener('message', (e) => {
  if (e.data && e.data.type === 'SKIP_WAITING') self.skipWaiting();
  if (e.data && e.data.type === 'CHECK_CACHED') {
    self.clients.matchAll().then((cls) => cls.forEach((cl) => cl.postMessage({ type: 'OFFLINE_READY' })));
  }
});

self.addEventListener('fetch', (e) => {
  const req = e.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== location.origin) return; // let cross-origin pass through
  // ---- installed multi-file ZIP apps: served from IndexedDB ----
  const zm = /^.*\/~zapps\/([A-Za-z0-9_-]+)\/?(.*)$/.exec(url.pathname);
  if (zm) { e.respondWith(serveZapp(zm[1], zm[2])); return; }
  if (req.cache === 'no-store') { e.respondWith(fetch(req)); return; } // live fetches (store refresh) bypass the cache
  e.respondWith((async () => {
    const cache = await caches.open(CACHE);
    const cached = await cache.match(req, { ignoreSearch: true });
    if (cached) {
      // stale-while-revalidate for the shell
      e.waitUtilNoop = 0;
      fetch(req).then((fresh) => { if (fresh && fresh.ok) cache.put(req, fresh.clone()); }).catch(() => {});
      return cached;
    }
    try {
      const fresh = await fetch(req);
      if (fresh && fresh.ok) cache.put(req, fresh.clone());
      return fresh;
    } catch (err) {
      return new Response('<h1>Offline</h1><p>This part of Leonux is not cached yet. Reopen the app once online.</p>', { headers: { 'Content-Type': 'text/html' }, status: 503 });
    }
  })());
});
